mapper.select:
SELECT

FROM users u


        AND u.level = #{level}


        AND EXISTS (SELECT 1 FROM user_address a WHERE a.user_id = u.id AND a.city = #{city})


        AND u.create_time >= #{start}



            ORDER BY u.create_time DESC


            ORDER BY u.id DESC



LIMIT #{offset}, #{size}

SELECT COUNT(*) FROM users u
WHERE u.mobile IN

    #{m}

SELECT COUNT(*) FROM orders o
WHERE o.remark = ${keyword}
  AND DATE(o.create_time) = #{day}

mapper.update:
UPDATE orders
status = #{status}, pay_time = #{payTime},
WHERE id = #{id} AND user_id = #{userId}

mapper.delete:
DELETE FROM order_item
WHERE order_id = #{orderId}
  AND quantity = 0
